parameters.jsCode:
const loopContext =
  $("Procesar extracciones una a una WF-014")
    .item
    .json
  ?? {};

const extractorOutput =
  $json
  ?? {};

const candidates = [
  extractorOutput.text,
  extractorOutput.content,
  extractorOutput.extracted_text,
  extractorOutput.extractedText,
  extractorOutput.data?.text,
  extractorOutput.pdf?.text,
];

let extractedText = '';

for (const candidate of candidates) {
  if (
    typeof candidate === 'string'
    && candidate.trim().length > 0
  ) {
    extractedText =
      candidate.trim();

    break;
  }
}

extractedText =
  extractedText
    .replace(/\u0000/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();

const minimumUsefulLength =
  100;

const extractionValid =
  extractedText.length >=
  minimumUsefulLength;

const rawPageCount =
  extractorOutput.numpages
  ?? extractorOutput.page_count
  ?? extractorOutput.pages
  ?? null;

const parsedPageCount =
  Number(rawPageCount);

const pageCount =
  Number.isFinite(parsedPageCount)
  && parsedPageCount > 0
    ? parsedPageCount
    : null;

return {
  json: {
    ...loopContext,
    ...extractorOutput,

    opportunity_document_id:
      loopContext.opportunity_document_id,

    organization_id:
      loopContext.organization_id,

    opportunity_analysis_id:
      loopContext.opportunity_analysis_id,

    process_id:
      loopContext.process_id,

    process_document_id:
      loopContext.process_document_id,

    process_reference:
      loopContext.process_reference,

    document_name:
      loopContext.document_name,

    file_extension:
      String(
        loopContext.file_extension
        ?? ''
      )
        .trim()
        .toLowerCase(),

    primary_category:
      loopContext.primary_category
      ?? 'other',

    extracted_text:
      extractedText,

    extracted_character_count:
      extractedText.length,

    extracted_page_count:
      pageCount,

    extraction_valid:
      extractionValid,

    extraction_error:
      extractionValid
        ? null
        : 'El extractor no produjo texto suficiente. El PDF puede ser una imagen escaneada o estar protegido.',

    extractor:
      'n8n_extract_from_pdf',

    extracted_at:
      new Date().toISOString(),
  },
};

